import{bQ as e,aL as d,u as o,G as a}from"./chunks/framework.CNL6o8_w.js";const _=JSON.parse('{"title":"设备上下线事件 (mapi 监听)","description":"","frontmatter":{},"headers":[],"relativePath":"lightsmart/gateway/online-event.md","filePath":"lightsmart/gateway/online-event.md"}'),c={name:"lightsmart/gateway/online-event.md"};function i(l,t,n,r,s,h){return d(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="设备上下线事件-mapi-监听" tabindex="-1">设备上下线事件 (mapi 监听) <a class="header-anchor" href="#设备上下线事件-mapi-监听" aria-label="Permalink to &quot;设备上下线事件 (mapi 监听)&quot;">​</a></h1><p>mapi 订阅 EMQX 系统主题，处理设备上下线事件。</p><h2 id="emqx-系统主题" tabindex="-1">EMQX 系统主题 <a class="header-anchor" href="#emqx-系统主题" aria-label="Permalink to &quot;EMQX 系统主题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>主题</th><th>方向</th><th>说明</th></tr></thead><tbody><tr><td><code>$SYS/brokers/{node}/clients/{clientid}/connected</code></td><td>EMQX → mapi</td><td>设备上线事件</td></tr><tr><td><code>$SYS/brokers/{node}/clients/{clientid}/disconnected</code></td><td>EMQX → mapi</td><td>设备下线事件</td></tr></tbody></table><h2 id="上线处理" tabindex="-1">上线处理 <a class="header-anchor" href="#上线处理" aria-label="Permalink to &quot;上线处理&quot;">​</a></h2><ol><li>解析 <code>$SYS/.../connected</code> 消息，提取 <code>username</code>（即 <code>mq_id</code>）</li><li>查 <code>license_tb</code>，仅处理 <code>license_type=1</code>（设备类型）</li><li>绑定 <code>server_id</code> 到当前 mapi 节点</li><li>延迟 1 秒后执行 <code>logConnect()</code>： <ul><li>更新 <code>device_mqtt_connect_tb</code>：写入 <code>device_id / connect_time / status=1</code>（并先将同一设备的旧记录置为断开）</li><li>更新 <code>device_tb.status = 1</code>（在线）</li></ul></li></ol><blockquote><p>延迟 1 秒是为了等待 MQTT 会话完全建立，避免在订阅未完成时就触发状态查询。</p></blockquote><h2 id="下线处理" tabindex="-1">下线处理 <a class="header-anchor" href="#下线处理" aria-label="Permalink to &quot;下线处理&quot;">​</a></h2><ol><li>解析 <code>$SYS/.../disconnected</code> 消息</li><li>清理 Redis 会话缓存：<code>redis.del(&quot;SH:ST:{mq_id}&quot;)</code><ul><li>清除设备实时状态缓存</li></ul></li><li>执行 <code>logDisconnect()</code>： <ul><li>更新 <code>device_mqtt_connect_tb</code>：按 <code>device_id + status=1</code> 匹配后写入 <code>disconnect_time / status=0</code></li><li>更新 <code>device_tb.status = 0</code>（离线）</li></ul></li></ol><h2 id="数据库表" tabindex="-1">数据库表 <a class="header-anchor" href="#数据库表" aria-label="Permalink to &quot;数据库表&quot;">​</a></h2><h3 id="device-mqtt-connect-tb" tabindex="-1">device_mqtt_connect_tb <a class="header-anchor" href="#device-mqtt-connect-tb" aria-label="Permalink to &quot;device_mqtt_connect_tb&quot;">​</a></h3><p>记录设备的 MQTT 连接历史：</p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>device_id</td><td>设备 ID（由 <code>license_tb.target_id</code> 取得，关联 <code>device_tb.id</code>）</td></tr><tr><td>connect_time</td><td>连接时间（秒）</td></tr><tr><td>disconnect_time</td><td>断开时间（秒）</td></tr><tr><td>status</td><td>1=连接中，0=已断开</td></tr></tbody></table><blockquote><p><strong>修订（2026-09-26 代码回源）</strong>：原表字段 <code>mq_id / clientid / node / connected_at / disconnected_at</code> 与代码不符。实际仅使用 <code>device_id / connect_time / disconnect_time / status</code>。依据 <code>service-lightsmart-mapi/src/model/mqtt.ts:12-40</code>。</p></blockquote><h3 id="device-tb-status" tabindex="-1">device_tb.status <a class="header-anchor" href="#device-tb-status" aria-label="Permalink to &quot;device_tb.status&quot;">​</a></h3><table tabindex="0"><thead><tr><th>值</th><th>含义</th></tr></thead><tbody><tr><td>0</td><td>离线</td></tr><tr><td>1</td><td>在线</td></tr></tbody></table><h2 id="redis-缓存清理" tabindex="-1">Redis 缓存清理 <a class="header-anchor" href="#redis-缓存清理" aria-label="Permalink to &quot;Redis 缓存清理&quot;">​</a></h2><p>设备下线时清理的 Redis Key：</p><table tabindex="0"><thead><tr><th>Key</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>SH:ST:{mq_id}</code></td><td>Hash</td><td>设备实时状态（field=naddr, value=hex 状态）</td></tr></tbody></table><blockquote><p>其他关联缓存（如 <code>SH:DEVICE:MAP:{mq_id}</code>、<code>SH:DEVICE:DATA:{mq_id}:{mac}</code>）在下线时不主动清理，由 TTL 过期机制自动回收。</p></blockquote>',20)])])}const m=e(c,[["render",i]]);export{_ as __pageData,m as default};
